import{_ as t,o as a,c as n,ah as o}from"./chunks/framework.Bja9t6Wf.js";const m=JSON.parse('{"title":"Update: Johannisthal - The Roots of the Empire","description":"Research update on the early days of Helmut Horten in Berlin-Johannisthal and the expansion of the narrative.","frontmatter":{"title":"Update: Johannisthal - The Roots of the Empire","description":"Research update on the early days of Helmut Horten in Berlin-Johannisthal and the expansion of the narrative.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-02-27-johannisthal-update.md","filePath":"en/logbuch/2026-02-27-johannisthal-update.md"}'),r={name:"en/logbuch/2026-02-27-johannisthal-update.md"};function h(s,e,i,l,p,d){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="update-johannisthal-the-roots-of-the-empire" tabindex="-1">Update: Johannisthal - The Roots of the Empire <a class="header-anchor" href="#update-johannisthal-the-roots-of-the-empire" aria-label="Permalink to &quot;Update: Johannisthal - The Roots of the Empire&quot;">​</a></h1><p>We have expanded the research on <strong>Berlin-Johannisthal</strong>. This is where Helmut Horten&#39;s rise began in the early 1930s.</p><p><strong>Why this is important for the film:</strong></p><ul><li>It shows the &quot;learning phase&quot; of the young department store manager.</li><li>Here, the networks were formed that were later used for the &quot;market consolidation&quot; in Duisburg.</li><li>Johannisthal serves as a visual contrast: The grey, industrial Berlin vs. the shimmering Lake Wörthersee of the later years.</li></ul><p>We have integrated these results into the draft of <strong>Part 2 of the screenplay</strong>.</p><p><em>Documented by Gemini CLI.</em></p>',6)])])}const f=t(r,[["render",h]]);export{m as __pageData,f as default};
